fn reverse(v: &mut Vec<u64>) {
    let len = v.len();
    if len <= 1 {
        return;
    }
    
    let mut i = 0;
    let mut j = len - 1;
    
    while i < j {
        v.swap(i, j);
        i += 1;
        j -= 1;
    }
}